export type TransformResult = {
    changedFiles: ProjectFile[]
    handledPaths: string[]
}

function getScriptKindFromPath(path: string): ts.ScriptKind {
    switch (pathModule.extname(path)) {
        case '.ts':
            return ts.ScriptKind.TS
        case '.js':
            return ts.ScriptKind.JS
        case '.json':
            return ts.ScriptKind.JSON
        default:
            return ts.ScriptKind.Unknown
    }
}

function isSysAppXml(filePath: string, scopeId: string): boolean {
    const fileName = pathModule.basename(filePath)
    return fileName === `sys_app_${scopeId}.xml` || fileName === `sys_store_app_${scopeId}.xml`
}

type IInspector = { inspect: (shape: Shape, ...plugins: Plugin[]) => void }
type ICommitter = { commit: CommitFunction }
type ITargeter = { getTarget: (shape: Shape, ...plugins: Plugin[]) => Promise<Result<ts.Node>> }
type FullContext = Omit<Context, 'self'> & IInspector & ICommitter

export class Project implements IProject {
    private readonly rootDir: string
    private readonly files: globalThis.Record<string, ProjectFile> = {}
    private readonly filesForDeletion: Set<string> = new Set<string>()
    private readonly plugins: Plugins
    private readonly fileSystem: FileSystem
    private readonly logger: Logger
    private readonly compiler: Compiler
    private readonly config: NowConfig
    private readonly package: Package
    private readonly keys: Keys
    private readonly diagnostics: Diagnostics
    private readonly transformService: Transform
    private readonly factory: Factory
    private readonly parser: Parser
    private readonly inspector: IInspector
    private readonly committer: ICommitter
    private readonly targeter: ITargeter
    private readonly context: FullContext
    private readonly telemetryClient: Telemetry
    private readonly pluginUsageTracker = new PluginUsageTracker()
    private readonly transformMode: 'transform' | 'type-generation'

    constructor({
        fileSystem = require('fs'),
        logger = createConsoleLogger(),
        rootDir = process && 'cwd' in process ? pathModule.normalize(process.cwd()) : '/',
        sourceFilePaths = [],
        compilerOptions = DEFAULT_COMPILER_OPTIONS,
        compiler = new Compiler(fileSystem, {
            rootDir,
            compilerOptions: { ...DEFAULT_COMPILER_OPTIONS, ...compilerOptions },
            sourceFilePaths,
            typesDir: pathModule.join('@types', 'servicenow'),
        }),
        plugins = PLUGINS,
        config,
        packageJson = createPackageJson({ rootDir, compiler, fileSystem }),
        keys,
        diagnostics = new DiagnosticsImpl(),
        transform,
        factory,
        parser,
        inspector,
        committer,
        targeter,
        telemetryClient,
        transformMode,
    }: {
        fileSystem?: FileSystem
        logger?: Logger
        rootDir?: string
        sourceFilePaths?: string[]
        compilerOptions?: CompilerOptions
        compiler?: Compiler
        config?: Partial<NowConfigOptions>
        packageJson?: Package
        plugins?: Plugin[] | Plugins
        keys?: Keys
        diagnostics?: Diagnostics
        transform?: Transform
        factory?: Factory
        parser?: Parser
        inspector?: IInspector
        committer?: ICommitter
        targeter?: ITargeter
        telemetryClient?: Telemetry
        transformMode?: 'transform' | 'type-generation'
    } = {}) {
        if (!pathModule.isAbsolute(rootDir)) {
            throw new Error(`Supplied root directory '${rootDir}' is not an absolute path`)
        }

        this.rootDir = rootDir
        this.plugins = plugins instanceof Plugins ? plugins : new Plugins(plugins)
        this.fileSystem = fileSystem
        this.logger = logger
        this.compiler = compiler
        this.config = config ? NowConfig.create(config) : NowConfig.load({ rootDir, compiler, fileSystem, logger })
        this.package = packageJson
        this.keys = keys ?? new KeysImpl(this)
        this.diagnostics = diagnostics
        this.transformService = transform ?? new MultiProjectTransform(this, this.pluginUsageTracker)
        this.factory = factory ?? new FactoryImpl(this)
        this.inspector = inspector ?? new Inspector(this)
        this.committer = committer ?? new Committer(this)
        this.targeter = targeter ?? new Targeter(this)
        this.parser = parser ?? new ParserImpl(this)
        this.context = {
            project: this,
            fs: this.fileSystem,
            logger: this.logger,
            compiler: this.compiler,
            diagnostics: this.diagnostics,
            config: this.config,
            packageJson: this.package,
            plugins: this.plugins,
            keys: this.keys,
            transform: this.transformService,
            factory: this.factory,
            parser: this.parser,
            inspect: this.inspector.inspect.bind(this.inspector),
            commit: this.committer.commit.bind(this.committer),
        }
        this.telemetryClient = telemetryClient ?? TelemetryFactory.create()
        this.transformMode = transformMode ?? 'transform'
        const fluentDir = pathModule.resolve(rootDir, this.config.fluentDir)
        const configFilePath = NowConfig.getFilePath(rootDir)
        const packageJsonPath = getPackageJsonFilePath(rootDir)

        const metadataDir = pathModule.resolve(rootDir, this.config.metadataDir)
        if (FileSystem.existsSync(this.fileSystem, metadataDir)) {
            this.addDirectory(metadataDir, false)
        }
        const staticDir = pathModule.resolve(rootDir, this.config.staticContentDir)
        if (FileSystem.existsSync(this.fileSystem, staticDir)) {
            this.addDirectory(staticDir, false)
        }

        if (process && 'env' in process) {
            const injectedPackages = process.env['FLUENT_INJECT_PLUGINS']
            if (injectedPackages) {
                const { createRequire } = require('node:module')
                const localRequire = createRequire(this.resolvePath('package.json'))
                for (const injectedPackage of injectedPackages.split(',').map((p) => p.trim())) {
                    if (!injectedPackage) {
                        continue
                    }

                    // Exported module could be a single plugin or array of plugins
                    const injectedPlugins = [localRequire(injectedPackage)].flat()
                    for (const { default: plugin } of injectedPlugins) {
                        if (
                            plugin &&
                            typeof plugin === 'object' &&
                            !Array.isArray(plugin) &&
                            plugin.constructor.name === 'Plugin'
                        ) {
                            this.plugins.prepend(plugin)
                        } else {
                            logger.error(
                                `Value from injected package "${injectedPackage}" is not a plugin: ${plugin} (${typeof plugin})`
                            )
                        }
                    }
                }
            }
        }

        this.registerFiles([
            this.keys.getSourceFile(),
            this.compiler.addSourceFileAtPathIfExists(configFilePath) ??
                this.compiler.createSourceFile(
                    configFilePath,
                    JSON.stringify({ scope: this.config.scope, scopeId: this.config.scopeId }, null, 4),
                    {
                        overwrite: true,
                        scriptKind: ts.ScriptKind.JSON,
                    }
                ),
            this.compiler.addSourceFileAtPathIfExists(packageJsonPath) ??
                this.compiler.createSourceFile(packageJsonPath, JSON.stringify(packageJson, null, 4), {
                    overwrite: true,
                    scriptKind: ts.ScriptKind.JSON,
                }),
            ...this.compiler.addFluentSourceFilesFromDirectory(fluentDir),
            ...this.compiler.addSourceFilesFromDirectory(
                this.resolvePath(this.config.serverModulesDir),
                this.config.serverModulesIncludePatterns,
                this.config.serverModulesExcludePatterns
            ),
        ])

        this.registerClaimsFile()
    }

    private registerClaimsFile() {
        const claimsFile = this.compiler.addSourceFileAtPathIfExists(
            this.resolvePath(this.config.generatedDir, CorePlugins.CLAIMS_FILE)
        )

        if (claimsFile) {
            validateClaimsFile(claimsFile.getFullText())
            this.registerFiles([claimsFile], false)
        }
    }

    private registerFiles(files: (ts.SourceFile | File)[], resolveDependencies = shouldResolveDependencies()): void {
        files.forEach((file) => {
            const path = file instanceof ts.SourceFile ? file.getFilePath() : file.path
            const existing = this.files[path]
            if (existing) {
                existing.reload(false)
            } else {
                this.files[path] = new ProjectFile(file, this)
            }
        })

        if (resolveDependencies) {
            this.compiler.resolveSourceFileDependencies()
        }
    }

    async getDocsMetadata(): Promise<DocsManifest> {
        const rawManifest = this.plugins.getDocsMetadata()
        const resolvedManifest: DocsManifest = {}

        // Find SDK installation location to resolve doc paths from there
        // This allows third-party plugins bundled with the SDK to have their docs resolved
        const sdkPackageJsonPath = await CorePlugins.resolveModule(
            '@servicenow/sdk/package.json',
            this.logger,
            this.fileSystem,
            this.rootDir
        )

        if (!sdkPackageJsonPath) {
            this.logger.warn('Could not find @servicenow/sdk installation, unable to resolve doc paths')
            return resolvedManifest
        }

        const sdkRoot = pathModule.dirname(sdkPackageJsonPath)

        for (const [apiName, entry] of Object.entries(rawManifest)) {
            const resolvedPath = await CorePlugins.resolveModule(
                entry.docPath,
                this.logger,
                this.fileSystem,
                sdkRoot // Resolve from SDK location, not user's project
            )

            if (resolvedPath) {
                resolvedManifest[apiName] = {
                    docPath: resolvedPath,
                    tags: entry.tags,
                }
            } else {
                this.logger.warn(`Could not resolve doc path for ${apiName}: ${entry.docPath}`)
            }
        }

        return resolvedManifest
    }

    getContext(): FullContext {
        return this.context
    }

    getTelemetryClient(): Telemetry {
        return this.telemetryClient
    }

    getPlugins(): Plugins {
        return this.plugins
    }

    getFileSystem(): FileSystem {
        return this.fileSystem
    }

    getLogger(): Logger {
        return this.logger
    }

    getDiagnosticsService(): Diagnostics {
        return this.diagnostics
    }

    getCompiler(): Compiler {
        return this.compiler
    }

    getKeys(): Keys {
        return this.keys
    }

    getConfig(): NowConfig {
        return this.config
    }

    getPackage(): Package {
        return this.package
    }

    getTransform(): Transform {
        return this.transformService
    }

    getFactory(): Factory {
        return this.factory
    }

    getFiles(): ProjectFile[] {
        return Object.values(this.files)
    }

    async getEntryPoints(): Promise<ProjectFile[]> {
        const context = this.getContext()
        const entryPoints: ProjectFile[] = []
        for (const file of this.getFiles()) {
            if (
                (file.isInMetadataDir() && !file.isInUiHtmlContentDir()) ||
                (await this.plugins.isEntryPoint(file.getPath(), context))
            ) {
                entryPoints.push(file)
            }
        }

        return entryPoints
    }

    getFileIfExists(path: string): ProjectFile | undefined {
        const absolutePath = this.resolvePath(path)
        return this.files[absolutePath]
    }

    getFile(path: string): ProjectFile {
        const file = this.getFileIfExists(path)
        if (file) {
            return file
        }

        throw new Error(`No file found at path: ${this.resolvePath(path)}`)
    }

    findFile(name: string): ProjectFile | undefined
    findFile(predicate: (file: ProjectFile) => boolean): ProjectFile | undefined
    findFile(nameOrPredicate: string | ((file: ProjectFile) => boolean)): ProjectFile | undefined {
        if (typeof nameOrPredicate === 'string') {
            return Object.entries(this.files).find(([p]) => pathModule.basename(p) === nameOrPredicate)?.[1]
        } else {
            return Object.values(this.files).find(nameOrPredicate)
        }
    }

    reloadFile(path: string, refreshFromFileSystem = true): ProjectFile {
        const absolutePath = this.resolvePath(path)
        let reloadedFile: ProjectFile
        if (absolutePath in this.files) {
            reloadedFile = this.getFile(path)
            reloadedFile.reload(refreshFromFileSystem)
        } else {
            reloadedFile = this.addFile(absolutePath)
        }
        return reloadedFile
    }

    reloadDirectory(path: string, refreshFromFileSystem = true): ProjectFile[] {
        const directoryPath = this.resolvePath(path)
        this.checkDirectoryExists(directoryPath)
        const reloadedFiles: ProjectFile[] = []

        const removedFilePaths: Set<string> = new Set()
        for (const filePath of Object.keys(this.files)) {
            if (this.resolvePath(filePath).startsWith(directoryPath)) {
                removedFilePaths.add(filePath)
            }
        }

        traverseDirectory(this.fileSystem, directoryPath, {
            visitor: ((filePath: string) => {
                removedFilePaths.delete(filePath)
                reloadedFiles.push(this.reloadFile(filePath, refreshFromFileSystem))
            }).bind(this),
        })

        // Remove files that are no longer present in the directory
        for (const filePath of removedFilePaths) {
            this.removeFile(filePath)
        }

        return reloadedFiles
    }

    addFile(file: File, options?: { resolveDependencies?: boolean; excludeFromCompiler?: boolean }): ProjectFile
    addFile(path: string, options?: { resolveDependencies?: boolean; excludeFromCompiler?: boolean }): ProjectFile
    addFile(
        fileOrPath: string | File,
        options?: { resolveDependencies?: boolean; excludeFromCompiler?: boolean }
    ): ProjectFile {
        this.addFiles(typeof fileOrPath === 'string' ? [fileOrPath] : [fileOrPath], options)
        return this.getFile(typeof fileOrPath === 'string' ? fileOrPath : fileOrPath.path)
    }

    private addFiles(
        files: (string | File)[],
        {
            resolveDependencies = shouldResolveDependencies(),
            excludeFromCompiler = false,
        }: { resolveDependencies?: boolean; excludeFromCompiler?: boolean } = {}
    ): ProjectFile[] {
        const unregisteredFiles = files.reduce(
            (unregistered, file) => {
                const { path, content } = typeof file === 'string' ? { path: file, content: undefined } : file
                const existingFile = this.getFileIfExists(path)
                if (existingFile) {
                    if (content !== undefined) {
                        existingFile.setContent(content)
                    }
                } else {
                    unregistered.push(file)
                }
                return unregistered
            },
            [] as (string | File)[]
        )

        const filesToRegister = unregisteredFiles.map((unregisteredFile) => {
            const { path, content } =
                typeof unregisteredFile === 'string' ? { path: unregisteredFile, content: undefined } : unregisteredFile
            const absolutePath = this.resolvePath(path)
            const kind = getScriptKindFromPath(path)

            let file: ts.SourceFile | File | undefined
            if (
                kind === ts.ScriptKind.Unknown ||
                path.startsWith(pathModule.join(this.rootDir, this.config.staticContentDir)) ||
                excludeFromCompiler
            ) {
                if (content !== undefined) {
                    file = { path: absolutePath, content }
                } else if (FileSystem.existsSync(this.fileSystem, absolutePath)) {
                    if (this.fileSystem.statSync(absolutePath).isDirectory()) {
                        throw new Error(`Cannot add directory as file: ${absolutePath}`)
                    }

                    file = {
                        path: absolutePath,
                        content: this.fileSystem.readFileSync(absolutePath).toString('utf-8'),
                    }
                } else {
                    throw new Error(`No file found at path: ${absolutePath}`)
                }
            } else {
                file =
                    content === undefined
                        ? this.compiler.addSourceFileAtPath(absolutePath)
                        : this.compiler.createSourceFile(absolutePath, content, {
                              overwrite: true,
                              scriptKind: getScriptKindFromPath(path),
                          })
            }

            if (absolutePath === getPackageJsonFilePath(this.rootDir)) {
                overwriteObject(
                    this.package,
                    createPackageJson({
                        rootDir: this.rootDir,
                        compiler: this.compiler,
                        fileSystem: this.fileSystem,
                    })
                )
            } else if (absolutePath === NowConfig.getFilePath(this.rootDir)) {
                overwriteObject(
                    this.config,
                    NowConfig.load({
                        rootDir: this.rootDir,
                        compiler: this.compiler,
                        fileSystem: this.fileSystem,
                        logger: this.logger,
                    })
                )
            }

            return file
        })

        this.registerFiles(filesToRegister, resolveDependencies)
        return files.map((file) => this.getFile(typeof file === 'string' ? file : file.path))
    }

    private checkDirectoryExists(path: string): void {
        if (!FileSystem.existsSync(this.fileSystem, path)) {
            throw Error(`No directory found at path: ${path}`)
        }

        if (!this.fileSystem.statSync(path).isDirectory()) {
            throw Error(`Expected directory but got file path: ${path}`)
        }
    }

    private addDirectory(path: string, resolveDependencies = shouldResolveDependencies()): ProjectFile[] {
        const directoryPath = this.resolvePath(path)
        this.checkDirectoryExists(directoryPath)

        const files: string[] = []

        traverseDirectory(this.fileSystem, directoryPath, {
            visitor: ((filePath: string) => {
                files.push(filePath)
            }).bind(this),
        })

        return this.addFiles(files, { resolveDependencies })
    }

    removeFile(file: ProjectFile): void
    removeFile(path: string): void
    removeFile(fileOrPath: ProjectFile | string): void {
        const file = fileOrPath instanceof ProjectFile ? fileOrPath : this.getFileIfExists(fileOrPath)
        if (file) {
            delete this.files[file.getPath()]
            file.remove()
        }
    }

    async transform(
        input: string | File | Shape | (string | File | Shape)[],
        { format = true }: TransformOptions = {}
    ): Promise<TransformResult> {
        const transformStartTime = Date.now()
        await this.getRecords() // Ensure all side effects are finished before transforming

        const inputs = Array.isArray(input) ? input : [input]
        const files: File[] = []
        const shapes: Shape[] = []

        for (const input of inputs) {
            if (typeof input === 'string') {
                const absolutePath = this.resolvePath(input)
                const subPaths: string[] = []
                if (this.fileSystem.statSync(absolutePath).isDirectory()) {
                    traverseDirectory(this.fileSystem, absolutePath, {
                        extensions: ['.xml'],
                        visitor: (path) => subPaths.push(path),
                    })
                } else {
                    subPaths.push(absolutePath)
                }

                files.push(
                    ...subPaths.map((path) => ({
                        path,
                        content: this.fileSystem.readFileSync(path).toString('utf-8'),
                    }))
                )
            } else if (input instanceof Shape) {
                shapes.push(input)
            } else {
                files.push({
                    path: this.resolvePath(input.path),
                    content: input.content,
                })
            }
        }

        const existingRecords = new Database()
        const metadataDirRecords = new Database()
        const existingRecordsParseStartTime = Date.now()
        for (const file of await this.getEntryPoints()) {
            this.logger.debug(`Parsing records from existing file: ${file.getPath()}`)
            const db = file.isInMetadataDir() ? metadataDirRecords : existingRecords
            db.insert(...(await file.getRecords(false)))
        }

        this.logger.debug(`Finished parsing existing records in ${Date.now() - existingRecordsParseStartTime}ms`)

        const incoming = new Project({
            compiler: this.compiler,
            fileSystem: this.fileSystem,
            logger: this.logger,
            rootDir: this.rootDir,
            config: this.config,
            packageJson: this.package,
            plugins: this.plugins,
            keys: this.keys,
        })

        const incomingRecords = new Database()
        const incomingRecordsParseStartTime = Date.now()
        const handledPaths = new Set<string>()
        for (const file of files.map((f) => incoming.addFile(f))) {
            const path = file.getPath()
            this.logger.debug(`Parsing records from incoming file: ${path}`)
            const isInMetadataDir = this.isInMetadataDir(path)

            let anyRecordInMeta: Record | undefined
            let ignoredRecord: Record | undefined
            const records = await file.getRecords(false)
            const recordsArray = records.query()
            if (file.isUpdateSetXml()) {
                const metadataCopyRecords: Record[] = []
                for (const record of recordsArray) {
                    const metadataDirRecord = metadataDirRecords.resolve(record.getId())
                    if (metadataDirRecord) {
                        metadataCopyRecords.push(record)
                    } else if (this.config.ignoreTransformTableList.includes(record.getTable())) {
                        metadataCopyRecords.push(record)
                    } else {
                        const attachmentShapes = await this.getAttachmentsForFields(records, record)
                        // Clear creator to allow any plugin to handle the new record
                        incomingRecords.insert(record.setCreator(undefined, true).merge(attachmentShapes))
                        handledPaths.add(path)
                    }
                }

                const metadataOutput = await getOutput(new Database(metadataCopyRecords), this.context)
                metadataOutput.forEach((metadata) => {
                    this.handleMetadataCopy(new ProjectFile(metadata, this))
                })
            } else {
                for (const record of recordsArray) {
                    const metadataDirRecord = metadataDirRecords.resolve(record.getId())
                    if (metadataDirRecord) {
                        anyRecordInMeta ??= metadataDirRecord
                        break
                    }
                    if (this.config.ignoreTransformTableList.includes(record.getTable())) {
                        ignoredRecord = record
                    }
                }

                if (!isInMetadataDir && anyRecordInMeta) {
                    this.logger.debug(
                        `Updating incoming ${anyRecordInMeta.getTable()} record with ID ${anyRecordInMeta.getId().getValue()} in metadata directory as XML`
                    )
                    this.handleMetadataCopy(file, anyRecordInMeta.getOriginalFilePath())
                } else if (ignoredRecord) {
                    this.logger.debug(
                        `Incoming ${ignoredRecord.getTable()} record with ID ${ignoredRecord.getId().getValue()} is in "ignoreTransformTableList" configuration and moved to metadata directory as XML`
                    )
                    this.handleMetadataCopy(file)
                } else if (!isInMetadataDir && recordsArray.length === 0) {
                    this.logger.info(`No records parsed from ${file.getName()}, moving to metadata directory`)
                    this.handleMetadataCopy(file)
                } else {
                    for (const record of records) {
                        const attachmentShapes = await this.getAttachmentsForFields(records, record)
                        // Clear creator to allow any plugin to handle the new record
                        incomingRecords.insert(record.setCreator(undefined, true).merge(attachmentShapes))
                        handledPaths.add(path)
                    }
                }
            }
        }

        //compare existing and incoming records
        const mergedDatabase = existingRecords.compare(incomingRecords)
        const changeDatabase = new DiffDatabase(existingRecords.query())
        const visitedRecords = new Database()
        for (const mode of ['explicit', 'catch-all'] as const) {
            for (const plugin of this.plugins.toArray()) {
                const changeRecords = await plugin.computeDiff({
                    mode,
                    existing: existingRecords,
                    incoming: incomingRecords,
                    context: this.getContext(),
                    visitedRecords,
                    mergedDatabase,
                })
                changeDatabase.insert(...changeRecords)
            }
        }

        await this.getKeys().commit()
        this.logger.debug(`Finished parsing incoming records in ${Date.now() - incomingRecordsParseStartTime}ms`)

        // This is a separate loop from the one above to make sure all side effects (like
        // registration of keys) are finished before we calculate the MD5 hashes
        const beforeFileHashes: globalThis.Record<string, string> = {}
        for (const file of this.getFiles()) {
            beforeFileHashes[file.getPath()] = MD5(file.getContent()).toString()
        }

        const context = this.getContext()
        const handledRecords = new Database()

        const shapeTransformStartTime = Date.now()
        for (const step of [
            // First, let plugins handle records they created and explicitly handle
            { mode: 'explicit', creatorOnly: true },

            // Then, let plugins handle records they created but don't explicitly handle
            { mode: 'catch-all', creatorOnly: true },

            // Then, let plugins handle records they didn't create but explicitly handle
            { mode: 'explicit', creatorOnly: false },

            // Finally, let any plugin handle any record
            { mode: 'catch-all', creatorOnly: false },
        ] as const) {
            for (const plugin of this.plugins.toArray()) {
                const result = await plugin.recordsToShapes({
                    ...step,
                    database: changeDatabase,
                    context,
                    handledRecords,
                    changedOnly: true,
                })

                if (result.success === 'partial' && result.unhandledRecords.length > 0) {
                    changeDatabase.insert(...result.unhandledRecords)
                }

                if (result.success === true || result.success === 'partial') {
                    shapes.push(...result.value)
                }
            }
        }

        this.logger.debug(`Finished transforming records into shapes in ${Date.now() - shapeTransformStartTime}ms`)

        const finalShapes: Shape[] = []
        if (this.isTypesGenerationMode()) {
            // convert callexpress into variable statement
            finalShapes.push(
                ...shapes.map((shape) => {
                    if (shape.is(CallExpressionShape)) {
                        const exportName = shape.getExportName()
                        if (!exportName) {
                            return shape
                        }

                        return new VariableStatementShape({
                            source: shape.getSource(),
                            isExported: true,
                            variableName: exportName,
                            initializer: shape,
                        })
                    }
                    return shape
                })
            )
        } else {
            finalShapes.push(...shapes)
        }

        const shapeCommitStartTime = Date.now()
        // Commit all the shapes, handling undefined first to ensure broken references are cleaned up
        for (const shape of finalShapes.sort((a) => (a.isUndefined() ? -1 : 0))) {
            const target = await this.targeter.getTarget(shape)
            if (target.success) {
                this.logger.debug(`Committing shape: ${shape.getDescription()}`)
                await context.commit(shape, target.value)
            }
        }

        this.logger.debug(`Finished committing shapes in ${Date.now() - shapeCommitStartTime}ms`)

        const affectedFiles: ProjectFile[] = []
        for (const file of this.getFiles()) {
            if (!beforeFileHashes[file.getPath()]) {
                affectedFiles.push(file)
                continue
            }

            const beforeHash = beforeFileHashes[file.getPath()]
            const afterHash = MD5(file.getContent()).toString()
            if (beforeHash !== afterHash) {
                affectedFiles.push(file)
            }
        }

        for (const file of affectedFiles) {
            file.fix()
            if (format) {
                await file.format()
            }

            file.reload(false)
        }

        this.logger.debug(`Transform completed in ${Date.now() - transformStartTime}ms`)

        return {
            changedFiles: affectedFiles,
            handledPaths: [...handledPaths],
        }
    }

    registerExplicitId(table: string, key: string | number, guidOverride?: string): string {
        return this.keys.registerExplicitId(table, key, guidOverride)
    }

    registerCoalesceId(table: string, key: CoalesceKeys, guidOverride?: string): string {
        return this.keys.registerCoalesceId(table, key, guidOverride)
    }

    async getOutput(sysIds?: Set<string>): Promise<File[]> {
        this.pluginUsageTracker.clearPluginToRecordUsage()

        const output = await this.getOutput0(sysIds)
        const sysApp = output.find((f) => isSysAppXml(f.path, this.config.scopeId))
        if (sysApp) {
            const packageJsonPath = NowConfig.moduleResolutionPath(this.config, this.package, false, 'package.json')
            if (updateSysApp(sysApp, packageJsonPath, this.package.version, this.config)) {
                this.logger.warn(
                    `Fixed package and version in sys_app output file: ${this.relativePath(sysApp.path)}\n` +
                        `This is likely due to a static sys_app XML file in the metadata directory. It is recommended to remove this file and allow the build system to generate one.`
                )
            }
        }

        this.telemetryClient.sendEvent(
            this.pluginUsageTracker.getRecordCountPerPlugin().map((data) => ({
                name: 'build.plugin',
                appInfo: { scopeId: this.config.scopeId },
                data,
            }))
        )

        return output
    }

    private async getOutput0(sysIds?: Set<string>): Promise<(File & { source?: Record })[]> {
        this.pluginUsageTracker.clearPluginToRecordUsage()
        const records = await this.getRecords(sysIds)
        const nonMetadataDirRecords = new Database(
            records.query().filter((r) => !this.isInMetadataDir(r.getOriginalFilePath()))
        )

        const files: globalThis.Record<string, { source?: Record; content: string }> = Object.fromEntries(
            (await getOutput(nonMetadataDirRecords, this.getContext())).map((f) => [
                f.path,
                { source: f.source, content: f.content },
            ])
        )

        const filesWithMetadata = this.copyMetadataRecords(files, records, sysIds)

        return Object.entries(filesWithMetadata).map(([path, sourceAndContent]) => ({ path, ...sourceAndContent }))
    }

    private copyMetadataRecords(
        files: globalThis.Record<string, { source?: Record; content: string }>,
        records: Database,
        sysIds?: Set<string>
    ) {
        if (!sysIds) {
            for (const file of this.getFiles().filter((f) => f.isInMetadataDir())) {
                const relativePath =
                    this.config.type === 'configuration'
                        ? file.getName()
                        : pathModule.relative(this.getMetadataDir(), file.getPath())
                files[this.resolvePath(this.config.appOutputDir, relativePath)] = { content: file.getContent() }
            }
            return files
        }

        const metadataDirRecords = new Database(
            records.query().filter((r) => this.isInMetadataDir(r.getOriginalFilePath()))
        )
        const specifiedMetadata = metadataDirRecords.query().filter((record) => sysIds.has(record.getId().getValue()))
        specifiedMetadata.forEach((record) => {
            const relativePath = pathModule.relative(this.getMetadataDir(), record.getOriginalFilePath())
            files[this.resolvePath(this.config.appOutputDir, relativePath)] = {
                content: (record.getSource() as File).content,
            }
        })

        return files
    }

    async getRecords(sysIds?: Set<string>): Promise<Database> {
        this.pluginUsageTracker.clearPluginToRecordUsage()
        // Collect all the defined records up front, BEFORE generating deletes
        const definedRecords: Record[] = []
        // Sort metadata dir records first so their sys IDs get registered, followed by server modules to ensure we compute their diagnostics first
        const projectFiles =
            this.config.type === 'package'
                ? (await this.getEntryPoints()).sort(
                      (f1, f2) =>
                          (f1.isInMetadataDir() ? 0 : f1.isInServerModulesDir() ? 1 : 2) -
                          (f2.isInMetadataDir() ? 0 : f2.isInServerModulesDir() ? 1 : 2)
                  )
                : (await this.getEntryPoints())
                      .filter((f) => !f.isInServerModulesDir())
                      .sort((f1, f2) => (f1.isInMetadataDir() ? 0 : 1) - (f2.isInMetadataDir() ? 0 : 1))

        for (const file of projectFiles) {
            // Reversing the array is a hack to preserve existing behavior for cases where plugins were implicitly dependent on ordering
            for (const record of (await file.getRecordsNoDedupe(false, sysIds)).reverse()) {
                definedRecords.push(record)
            }
        }

        //FIXME: reiterate over files to recompute the typescript diagnostics now that we have processed all table entities
        const fluentFiles = projectFiles.filter((f) => pathModule.basename(f.getPath()).endsWith(NOW_FILE_EXTENSION))
        for (const file of fluentFiles) {
            this.compiler.getDiagnosticsForFluentFile(file.getPath()).forEach((diagnostic) => {
                this.diagnostics.add(diagnostic)
            })
        }

        const warnings = this.diagnostics.getWarnings()
        warnings.forEach((w) => this.logger.warn(w.getFormattedText()))

        const errors = this.diagnostics.getErrors()
        if (errors.length > 0) {
            errors.forEach((e) => this.logger.error(e.getFormattedText()))
            throw new Error(`Found ${errors.length} diagnostic error(s) while building the project.`)
        }

        // Now it's safe to generate deletes since all keys should be registered at this point
        const records =
            sysIds || this.config.type === 'configuration' ? new Database() : this.generateRecordsFromDeletedKeys()
        const generatedDeletes = new WeakSet(records.query())
        /**  Self Conflicting Scenarios:
         * 1. Deletes in the metadata dir can conflict with themselves, so we need to check for that scenario.
         * 2. Records with same sources, happens since we parse child nodes first and then the parent node.
         * ex: Consider default exporting record call, we generate a record for the call expression node first and
         * then for export assignment. Since both records originate from same source we shouldn't log any conflict warnings.
         */
        const isSelfConflicting = (record: Record, conflict: Record) =>
            (this.isInMetadataDir(record.getOriginalFilePath()) &&
                record.isDeleted() &&
                generatedDeletes.has(conflict)) ||
            record.getOriginalSource() === conflict.getOriginalSource()

        // Metadata dir records can conflict with other metadata dir records, but this information is not helpful to the user
        const isMetadataDirOnlyConflict = (record: Record, conflict: Record) =>
            this.isInMetadataDir(record.getOriginalFilePath()) && this.isInMetadataDir(conflict.getOriginalFilePath())

        const isModuleConflict = (record: Record, conflict: Record) =>
            record.getTable() === 'sys_module' && conflict.getTable() === 'sys_module'

        // Insert the defined records in reverse order so that metadata dir records come last and take precedence
        const conflicts: globalThis.Record<string, Record[]> = {}
        for (const record of definedRecords.reverse()) {
            const conflict = records.resolve(record.getId())
            if (
                conflict &&
                !isSelfConflicting(record, conflict) &&
                !isMetadataDirOnlyConflict(record, conflict) &&
                !isModuleConflict(record, conflict)
            ) {
                ;(conflicts[`${conflict.getTable()}.${conflict.getId().getValue()}`] ??= [conflict]).push(record)
            }

            records.insert(record)
        }

        for (const [updateName, conflictingRecords] of Object.entries(conflicts)) {
            this.logger.warn(
                `Record "${updateName}" is defined ${conflictingRecords.length} times in the project:\n    ${conflictingRecords
                    .map((r, i) => {
                        const path = this.relativePath(r.getOriginalFilePath())
                        const source = r.getOriginalSource()
                        const deleted = r.isDeleted() ? ' (delete)' : ''
                        const line = ts.Node.isNode(source) ? `:${source.getStartLineNumber(false)}` : ''
                        return `${i + 1}. ${path}${line}${deleted}`
                    })
                    .join('\n    ')}`
            )
        }

        const conflictCount = Object.keys(conflicts).length
        if (conflictCount > 0) {
            this.logger.warn(
                `Total of ${conflictCount} conflicts found. The last entry from each conflict will take precedence.`
            )
        }

        // Group records by their keys to find duplicates
        const recordsByKey = new Map<string | number, Record[]>()
        records.query().forEach((record) => {
            const key = record.getId().getNowIdKey()

            if (key !== undefined && record.getTable() !== 'sys_module') {
                recordsByKey.set(key, [...(recordsByKey.get(key) ?? []), record])
            }
        })

        // Find and log records with duplicate keys
        const duplicateKeys = Array.from(recordsByKey.entries()).filter(([_, records]) => records.length > 1)
        if (duplicateKeys.length > 0) {
            duplicateKeys.forEach(([key, records]) => {
                this.logger.error(
                    `Explicit key "${key}" is defined multiple times in the project:\n    ${records
                        .map((r, i) => {
                            const path = this.relativePath(r.getOriginalFilePath())
                            const source = r.getOriginalSource()
                            const line = ts.Node.isNode(source) ? `:${source.getStartLineNumber(false)}` : ''
                            const table = r.getTable()
                            return `${i + 1}. [${table}] ${path}${line}`
                        })
                        .join('\n    ')}`
                )
            })
            throw new Error(`Found ${duplicateKeys.length} duplicate explicit key(s) in the project.`)
        }

        await this.getKeys().commit()
        return records
    }

    private async getAttachmentsForFields(database: Database, record: Record) {
        const updateName = await this.getTransform().getUpdateName(record)
        return Object.fromEntries(
            database
                .query('sys_attachment', {
                    table_name: `ZZ_YY${record.getTable()}`,
                    table_sys_id: record.getId().getValue(),
                })
                .map((attachment) => {
                    return [
                        attachment.get('file_name').toString().getValue(),
                        CorePlugins.NowAttachShape.fromAttachmentRecord(
                            updateName,
                            attachment,
                            database.query('sys_attachment_doc', {
                                sys_attachment: attachment.getId().getValue(),
                            })
                        ),
                    ]
                })
        ) as globalThis.Record<string, CorePlugins.NowAttachShape>
    }

    private generateRecordsFromDeletedKeys(): Database {
        const database = new Database()
        const source = this.getKeys().getSourceFile()

        for (const { table, id, key: rawKey } of this.getKeys().getEffectiveDeletedKeys()) {
            if (table === 'sys_ui_view') {
                continue // TODO: When the installer is fixed to prevent out-of-scope deletion, we can stop being so cautious here
            } else if (table === 'sys_user_role') {
                const scope = this.getConfig().scope
                const name = rawKey?.['name'] as string | undefined
                if (name && typeof name === 'string' && !name.startsWith(scope)) {
                    continue
                }
            }

            const key = Object.fromEntries(
                Object.entries(rawKey ?? {}).map(([k, v]) => [
                    k,
                    typeof v === 'string'
                        ? v === 'NULL'
                            ? undefined
                            : v
                        : new RecordId({
                              source,
                              guid: v.id,
                              table: k,
                              keys: Object.fromEntries(
                                  Object.entries(v.key).map(([k, v]) => [k, typeof v === 'string' ? v : v.id])
                              ),
                          }),
                ])
            )

            database.insert(
                new Record({
                    source,
                    action: 'DELETE',
                    installCategory: 'author_elective_update',
                    properties: key,
                    id: new RecordId({
                        source,
                        table,
                        guid: id,
                    }),
                })
            )
        }

        return database
    }

    async getDiagnostics(): Promise<Diagnostic[]> {
        this.pluginUsageTracker.clearPluginToRecordUsage()

        const diagnostics = new DiagnosticsImpl()
        const entryPoints = await this.getEntryPoints()
        entryPoints.sort((a, _b) => {
            return this.isInServerDir(a.getPath()) ? -1 : 1
        })

        for (const file of entryPoints) {
            if (file.isInMetadataDir()) {
                continue
            }

            for (const diagnostic of await file.getDiagnostics()) {
                diagnostics.add(diagnostic)
            }
        }

        //FIXME: reiterate over files to recompute the typescript diagnostics now that we have processed all table entities
        const fluentFiles = entryPoints.filter((f) => pathModule.basename(f.getPath()).endsWith(NOW_FILE_EXTENSION))
        for (const file of fluentFiles) {
            this.compiler.getDiagnosticsForFluentFile(file.getPath()).forEach((diagnostic) => {
                diagnostics.add(diagnostic)
            })
        }

        return diagnostics.getAll()
    }

    isInDir(dir: string, path: string): boolean {
        const relativePath = pathModule.relative(this.resolvePath(dir), this.resolvePath(path))
        return !relativePath.startsWith('..')
    }

    getRootDir(): string {
        return this.rootDir
    }

    isInRootDir(path: string): boolean {
        return this.isInDir(this.getRootDir(), path)
    }

    getMetadataDir(): string {
        return this.resolvePath(this.config.metadataDir)
    }

    isInMetadataDir(path: string): boolean {
        return this.isInDir(this.getMetadataDir(), path)
    }

    isInUiHtmlContentDir(path: string) {
        return this.isInDir(pathModule.join(this.getMetadataDir(), 'ui.html'), path)
    }

    private getSnDirName(path: string): string {
        const dirName = pathModule.basename(pathModule.dirname(path))
        const snDirNames = [
            'update',
            'author_elective_update',
            'dictionary',
            'scope',
            'demo',
            'unload',
            'unload.demo',
            'apply_once',
            'if',
        ]
        return snDirNames.includes(dirName) ? dirName : ''
    }

    getFluentDir(): string {
        return this.resolvePath(this.config.fluentDir)
    }

    isInFluentDir(path: string): boolean {
        return this.isInDir(this.getFluentDir(), path)
    }

    getServerDir(): string {
        return this.resolvePath(this.config.serverModulesDir)
    }

    isInServerDir(path: string): boolean {
        return this.isInDir(this.getServerDir(), path)
    }

    resolvePath(...paths: string[]): string {
        const path = pathModule.join(...paths)
        return pathModule.isAbsolute(path) ? pathModule.normalize(path) : pathModule.resolve(this.rootDir, path)
    }

    relativePath(...paths: string[]): string {
        return pathModule.relative(this.rootDir, this.resolvePath(...paths))
    }

    dispose(): void {
        this.compiler.getLanguageService().compilerObject.dispose()
    }

    async fix(): Promise<void[]> {
        return Promise.all(this.getFiles().map((file) => file.fix()))
    }

    async format(): Promise<void[]> {
        const formatter = new Formatter(this.fileSystem)
        return Promise.all(this.getFiles().map((file) => file.format(formatter)))
    }

    save(): void {
        this.getFiles().forEach((file) => file.save())
        this.filesForDeletion.forEach((path) => this.fileSystem.rmSync(path, { force: true }))
    }

    async saveOutput(sysIds?: Set<string>): Promise<File[]> {
        const output = await this.getOutput(sysIds)
        output.forEach((file) => writeFileWithParentDirs(this.fileSystem, file))
        return output
    }

    deleteFile(path: string): void {
        this.removeFile(path)
        this.filesForDeletion.add(path)
    }

    handleMetadataCopy(file: ProjectFile, metadataDirRecordPath?: string): ProjectFile {
        let destinationPath: string
        if (metadataDirRecordPath && file.getName() === pathModule.basename(metadataDirRecordPath)) {
            // Update an existing record in metadata folder
            destinationPath = metadataDirRecordPath
        } else {
            // Preserve directory from incoming metadata record if there is one
            destinationPath = pathModule.join(
                this.getMetadataDir(),
                this.getSnDirName(file.getPath()),
                pathModule.basename(file.getPath())
            )
        }

        return this.addFile({
            content: file.getContent(),
            path: destinationPath,
        })
    }

    isTypesGenerationMode(): boolean {
        return this.transformMode === 'type-generation'
    }
}

function updateSysApp(sysAppFile: File, packageJsonPath: string, sysAppVersion: string, config: NowConfig) {
    const parser = new XMLParser({
        ignoreAttributes: false,
        ignoreDeclaration: false,
    })
    const parsedSysAppXml = parser.parse(sysAppFile.content)
    const appElement = parsedSysAppXml['record_update']['sys_app'] || parsedSysAppXml['record_update']['sys_store_app']

    const builder = new XMLBuilder({
        format: true,
        indentBy: '    ',
        ignoreAttributes: false,
        suppressEmptyNode: true,
    })

    const updatedPackageJsonPath = updateSysAppWithPackageJsonPath(appElement, packageJsonPath, sysAppVersion)
    const updatedPackageResolver = updateSysAppWithPackageResolverVersion(appElement, config)

    if (updatedPackageJsonPath || updatedPackageResolver) {
        //fxp adds new line after xml declaration while instance doesn't
        sysAppFile.content = builder.build(parsedSysAppXml).replace(/(<\?xml[^>]*\?>)\s*/, '$1')
        return true
    }

    return false
}

function updateSysAppWithPackageResolverVersion(appElement: any, config: NowConfig): boolean {
    const legacyResolver = NowConfig.legacyPackageResolution(config)
    if (appElement.package_resolver_version) {
        return false
    }

    appElement.package_resolver_version = legacyResolver ? MODULE_RESOLUTION.V1 : MODULE_RESOLUTION.V2
    return true
}

function updateSysAppWithPackageJsonPath(appElement: any, packageJsonPath: string, sysAppVersion: string): boolean {
    if (appElement.version && appElement.version === sysAppVersion && appElement.package_json === packageJsonPath) {
        return false
    }

    appElement.package_json = packageJsonPath
    if (sysAppVersion) {
        appElement.version = sysAppVersion
    }

    return true
}

function overwriteObject(target: globalThis.Record<string, unknown>, source: globalThis.Record<string, unknown>): void {
    for (const key in target) {
        delete target[key]
    }

    Object.assign(target, source)
}

function shouldResolveDependencies(): boolean {
    const envValue = process.env['FLUENT_RESOLVE_DEPENDENCIES']
    if (envValue === undefined || envValue === '') {
        return true
    }
    return envValue !== 'false' && envValue !== '0'
}
